BEGIN;

DROP TABLE IF EXISTS daily_store_sales CASCADE;
DROP TABLE IF EXISTS stores CASCADE;

CREATE TABLE stores (
  store_id INTEGER PRIMARY KEY,
  store_code VARCHAR(20) UNIQUE NOT NULL,
  store_name VARCHAR(120) NOT NULL,
  city VARCHAR(40) NOT NULL,
  region VARCHAR(20) NOT NULL,
  store_format VARCHAR(20) NOT NULL,
  open_date DATE NOT NULL,
  manager_name VARCHAR(80) NOT NULL
);

CREATE TABLE daily_store_sales (
  sales_id BIGSERIAL PRIMARY KEY,
  sales_date DATE NOT NULL,
  store_id INTEGER NOT NULL REFERENCES stores(store_id),
  orders_count INTEGER NOT NULL,
  gross_revenue NUMERIC(12,2) NOT NULL,
  discount_amount NUMERIC(12,2) NOT NULL,
  refund_amount NUMERIC(12,2) NOT NULL,
  net_revenue NUMERIC(12,2) NOT NULL,
  member_orders INTEGER NOT NULL,
  channel_mix VARCHAR(20) NOT NULL
);

CREATE INDEX idx_daily_store_sales_date ON daily_store_sales(sales_date);
CREATE INDEX idx_daily_store_sales_store_id ON daily_store_sales(store_id);



COMMIT;
